import{_ as e,o as a,c as o,a5 as s}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"第七章：实现 top-level await 支持","description":"好！我们进入 第七章：支持 top level await 的异步模块加载器 ，这是现代 ESM 的一大亮点，也是 Webpack、Vite 等工具所支持的功能。 ⚙️ ✅ 本章目标： 让模块可以在顶层使用 await 加载模块时正确等待依赖执行完成 模拟 async 的模块执行。","frontmatter":{"title":"第七章：实现 top-level await 支持","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","模块化与工程化"],"description":"好！我们进入 第七章：支持 top level await 的异步模块加载器 ，这是现代 ESM 的一大亮点，也是 Webpack、Vite 等工具所支持的功能。 ⚙️ ✅ 本章目标： 让模块可以在顶层使用 await 加载模块时正确等待依赖执行完成 模拟 async 的模块执行。","sidebarWeight":42,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/12-模块化编程/实现esmodule/第七章：实现 top-level await 支持.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第七章：实现 top-level await 支持.md","filePath":"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第七章：实现 top-level await 支持.md"}'),r={name:"posts/JavaScript系统教程/06-模块化与工程化/实现esmodule/第七章：实现 top-level await 支持.md"};function n(l,t,p,i,d,c){return a(),o("div",null,[...t[0]||(t[0]=[s('<div><h1 id="第七章-实现-top-level-await-支持" tabindex="-1">第七章：实现 top-level await 支持 <a class="header-anchor" href="#第七章-实现-top-level-await-支持" aria-label="Permalink to &quot;第七章：实现 top-level await 支持&quot;">​</a></h1><blockquote><p>本节目标：理解“第七章：实现 top-level await 支持”的核心思路，并能把它用于实际开发或面试表达。 好！我们进入 <strong>第七章：支持 top-level await 的异步模块加载器</strong>，这是现代 ESM 的一大亮点，也是 Webpack、Vite 等工具所支持的功能。</p></blockquote><p><strong>⚙️</strong> ✅ 本章目标：</p><ul><li>让模块可以在顶层使用 await</li><li>加载模块时正确等待依赖执行完成</li><li>模拟 async 的模块执行调度器</li></ul><p><strong>🧠</strong> <strong>背景知识：什么是 top-level await？</strong> 以前 JS 顶层不能直接写 await，只能在 async 函数里： await fetch(...); // ❌ 不合法 而现在 ESM 模块中可以这样写： // a.mjsawait new Promise(r =&gt; setTimeout(r, 1000));export const foo = &#39;ready&#39;; 这意味着模块加载顺序和执行控制也要支持 Promise。</p><p><strong>🧪</strong> <strong>文件结构</strong> awaitbundler/├── src/│ ├── a.mjs│ └── main.mjs├── loader.js # ✅ 支持 top-level await 的加载器└── run.js # 启动入口</p><p><strong>📄</strong> <strong>src/a.mjs</strong> await new Promise(resolve =&gt; setTimeout(resolve, 1000));export const msg = &#39;Top-level await is done&#39;; <strong>📄</strong> <strong>src/main.mjs</strong> import { msg } from &#39;./a.mjs&#39;;console.log(&#39;Main got msg:&#39;, msg);</p><p><strong>📦</strong> <strong>loader.js — 实现异步加载器</strong> const fs = require(&#39;fs&#39;);const path = require(&#39;path&#39;);const acorn = require(&#39;acorn&#39;); const moduleGraph = new Map(); async function loadModule(filePath) { const absPath = path.resolve(__dirname, filePath); if (moduleGraph.has(absPath)) return moduleGraph.get(absPath).namespace; const code = fs.readFileSync(absPath, &#39;utf-8&#39;); const ast = acorn.parse(code, { ecmaVersion: &#39;latest&#39;, sourceType: &#39;module&#39; }); const deps = []; ast.body.forEach(node =&gt; { if (node.type === &#39;ImportDeclaration&#39;) { deps.push(node.source.value); } }); const namespace = {}; moduleGraph.set(absPath, { namespace }); // 先加载依赖（await 递归） for (const dep of deps) { const depPath = dep.endsWith(&#39;.mjs&#39;) ? dep : dep + &#39;.mjs&#39;; const depAbs = path.resolve(path.dirname(absPath), depPath); const depNS = await loadModule(depAbs); // 依赖导出绑定 Object.keys(depNS).forEach(key =&gt; { Object.defineProperty(namespace, key, { enumerable: true, get: () =&gt; depNS[key], }); }); } // 包装为 async 函数并执行支持顶层 await const wrapped = <code>return async function(namespace, exports) { ${code.replace(/export\\s+const\\s+(\\w+)\\s*=\\s*(.*);/g, (_, name, value) =\\&gt; { return</code>const ${name} = ${value}; exports.${name} = ${name};<code>; })} } </code>; const factory = new Function(wrapped)(); await factory(namespace, namespace); return namespace;} module.exports = { loadModule };</p><p><strong>🚀</strong> <strong>run.js — 执行入口</strong> const { loadModule } = require(&#39;./loader&#39;); (async () =&gt; { await loadModule(&#39;./src/main.mjs&#39;);})();</p><p><strong>✅</strong> <strong>运行</strong> node run.js <strong>输出：</strong> Main got msg: Top-level await is done</p><p><strong>🧠</strong> <strong>实现说明</strong></p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>关键点</strong></td><td><strong>实现方式</strong></td></tr><tr><td>顶层 await 支持</td><td>用 async function 包裹模块</td></tr><tr><td>依赖异步加载递归</td><td>await loadModule(dep)</td></tr><tr><td>保留模块导出</td><td>exports.xxx = xxx</td></tr><tr><td>动态构造并执行模块代码</td><td>new Function(...)</td></tr></tbody></table><p><strong>✅</strong> <strong>本章成果</strong></p><ul><li>✔ 支持顶层 await 的模块加载</li><li>✔ 保证依赖关系加载顺序</li><li>✔ 所有模块 async 运行并支持模块导出引用</li></ul><p><strong>🔮</strong> <strong>下一章预告（第八章）</strong> 你已经拥有一个具备模块系统核心功能的加载器了，下一步可以考虑：</p><ol><li>🌳 <strong>按需分析和打包 — Tree Shaking + Async Graph 合并</strong></li><li>🔧 <strong>代码分割（Code Splitting）</strong>，生成多个 chunk 动态加载</li><li>🧩 <strong>动态导入 (import() 函数) 支持</strong></li><li>🧱 <strong>使用缓存提高加载性能</strong></li></ol><p>继续进入第八章吗？我们可以挑战更像 Rollup/Vite 的真实打包器能力 💪 &gt; 来自 &lt;<a href="https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985" target="_blank" rel="noreferrer">https://chatgpt.com/c/6805aef6-e7b4-8004-ab43-9a137f666985</a>&gt;</p></div>',1)])])}const u=e(r,[["render",n]]);export{m as __pageData,u as default};
